use std::{fs,path::Path,collections::{BTreeMap,BTreeSet},fmt::Write};use serde_json::{Value,json};use sha2::{Digest,Sha256};
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){let r=Path::new("/tmp/zopro-modal-scalar-census");let pins:BTreeMap<String,String>=serde_json::from_value(read(r.join("input-pins.json"))).unwrap();for(p,h)in &pins{assert_eq!(hash(p),*h,"{p}");}assert_eq!(pins.len(),204);assert_eq!(read(r.join("run/result.json"))["status"],"complete");for step in ["link","census"]{let p=r.join("run").join(step);let e=read(p.join("exit.json"));assert_eq!(e["success"],true);for stream in ["stdout","stderr"]{assert_eq!(hash(p.join(format!("{stream}.log"))),e[format!("{stream}_sha256")].as_str().unwrap());}}
let out=fs::read_to_string(r.join("run/census/stdout.log")).unwrap();let rows=out.lines().filter_map(|l|l.strip_prefix("ROW ")).map(|l|serde_json::from_str::<Value>(l).unwrap()).collect::<Vec<_>>();assert_eq!(rows.len(),27);let synthetic=out.lines().filter(|l|l.starts_with("SYNTHETIC ")).count();assert_eq!(synthetic,4);let mut seen=BTreeSet::new();for v in &rows{assert!(seen.insert((v["shape"].as_str().unwrap(),v["query"].as_str().unwrap())));assert_eq!(v["raw_and_solver_image_solutions_equal"],true);let s=&v["stats"];assert_eq!(s["mode_kind"],"zero");assert_eq!(s["modeled_saved_group_formation_additions"],0);assert_eq!(s["independent_weighted_field_checks"],2);assert_eq!(s["positions"],s["original_positions_accounted_once"]);}assert!(out.lines().last().unwrap().starts_with("COMPLETE "));
let result=json!({"status":"closed_verified","rows":rows,"pins_rehashed":204,"explicit_scalar_solves":18,"raw_vs_image_solution_vector_agreements":9,"query_weighted_field_checks":54,"synthetic_cases":4,"synthetic_weighted_field_checks":8,"all_mode_zero":true,"modeled_formation_additions_saved":0,"new_sdk_proofs":0,"new_gnark_exports":0,"accepted_170_sources_unchanged":true,"adopted":false,"goal_achieved":false,"decision":"Global modal scalar translation has no class-formation saving on these27vectors: zero already wins every population. Do not implement aggregate-key-point preparation for this global design.","next":"Separately screen lossless local pair/Fenwick query basis transforms: no extra key points, scalar differences may expose zeros. Include changed duplicate grouping/admission and signed digit work, not only count zeros. No point rewrite or latency claim until opportunity is established."});fs::write(r.join("results.json"),serde_json::to_vec_pretty(&result).unwrap()).unwrap();
let report=Path::new("/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-26-modal-scalar-census");fs::create_dir(report).unwrap();let mut s=String::from("# Global modal scalar translation census\n\nZero is already the most frequent scalar in all 27 fresh query vectors across nine fixtures. Changing the grouping origin to the modal scalar therefore removes no class-formation additions. No aggregate key-point preparation, curve implementation or latency trial follows. Production is unchanged.\n\nThe proposed identity is sum(s_i P_i)=c*sum(P_i)+sum((s_i-c)P_i). One key-only aggregate point could let grouping omit a frequent nonzero scalar class instead of zero. This differs from [opposite-scalar grouping](../2026-10-26-opposite-scalar-census/README.md): occurrence frequency, rather than unique class count, determines the potential saving. It requires no lookup table. The population screen rejects the global version before any key transformation.\n\n| Shape | Query | Positions | Zero occurrences | One occurrences | Modal value | Modeled formation additions saved |\n| --- | --- | ---: | ---: | ---: | --- | ---: |\n");for v in result["rows"].as_array().unwrap(){let t=&v["stats"];writeln!(s,"| {} | {} | {} | {} | {} | zero | 0 |",v["shape"].as_str().unwrap(),v["query"].as_str().unwrap(),t["positions"],t["zero_occurrences"],t["one_occurrences"]).unwrap();}
s.push_str("\nAll 27 vectors pass two independent deterministic weighted-Fr reconstructions of the complete translation identity. Every row is accounted once. Four synthetic all-zero, all-one, one-dominant/random and zero-dominant/random populations add eight field checks. Nine raw/cached-image solution-vector comparisons agree, from 18 explicit public scalar solves. All 204 source/library/key/fixture pins and link/run receipts match after execution. The model counts grouping additions as sum(count-1); key-sum setup, changed scalar digits and output correction are not treated as free.\n\nRaw K is diagnostic rather than accepted folded K/Euler H. Exact grouping populations do not reproduce all sampling/admission choices, and one fixture per shape does not establish a property of arbitrary witnesses. No private scalar, witness, point or proof arrays are exported. No new SDK proof, Gnark export, latency, minimum-RAM, physical-device or AWS result is claimed.\n\nA possible next screen is a lossless local difference basis: replace (P,Q) by (P+Q,Q) and (a,b) by (a,b-a). The point count stays fixed, arbitrary inputs remain valid, and equal nearby scalars produce zeros. A recursive binary transform can generalize this to bounded blocks. This is not yet implemented or measured. It must count the effect on duplicate grouping and digit work, since extra zeros alone can conceal more distinct nonzero scalars.\n\nAccepted primary remains historically 8.594267 ms and merge54 178.891799 ms. The unchanged [accepted CPU/Metal comparisons for all supplied shapes](../2026-10-25-grouping-module/artifacts/perf/report.md) remain authoritative; all eight CPU 10× targets are unmet.\n\n[Protocol](artifacts/experiment.json), [results](artifacts/results.json), [driver](artifacts/probe.rs), [workflow](artifacts/plan.json), [input pins](artifacts/input-pins.json).\n");fs::write(report.join("README.md"),s).unwrap();println!("CLOSED27vectors18solves54+8fieldchecks204pins; zeroisthemodeeverywhere, no pointprototype");}
